Using the lesson's refresh-token store (rotation with reuse detection, where a replayed used token revokes its whole family), what does this print?

```python
class ReuseDetected(Exception): pass

class Store:
    def __init__(self): self.t = {}; self.used = set(); self.rev = set(); self.n = 0
    def _new(self, f): self.n += 1; i = f"r{self.n}"; self.t[i] = f; return i
    def login(self, u): return self._new("fam:" + u)
    def rotate(self, i):
        f = self.t.get(i)
        if f is None or f in self.rev: raise PermissionError("invalid")
        if i in self.used: self.rev.add(f); raise ReuseDetected(i)
        self.used.add(i); return self._new(f)

s = Store(); r1 = s.login("a"); r2 = s.rotate(r1)
for tok in (r1, r2, r1):
    try:
        print("ok", s.rotate(tok))
    except Exception as e:
        print(type(e).__name__)
```
